// Generated by tools/gen-samples.mjs from samples/. Do not edit.
(function (LG) {
  LG.SAMPLE_FILES = {"bounce.lgo":"; BOUNCE.LGO - several turtles bouncing around at once\n;\n; TELL picks which turtles the next commands go to. ASK sends commands\n; to one turtle without changing who you are talking to. Each turtle\n; keeps its own position, heading and pen.\n\nto setup\n  for [t 0 4] [\n    ask :t [penup home setheading 20 + 70 * :t setpencolor :t + 1 setshape \"circle showturtle pendown]\n  ]\nend\n\nto move.all\n  for [t 0 4] [\n    ask :t [\n      forward 6\n      if or (xcor > 390) (xcor < -390) [setheading 0 - heading]\n      if or (ycor > 290) (ycor < -290) [setheading 180 - heading]\n    ]\n  ]\nend\n\nclearscreen\nsetup\nrepeat 600 [move.all wait 1]\n","clock.lgo":"; CLOCK.LGO - a clock that keeps time\n;\n; TIME gives the day, date and time as a list. ITEM 4 of it is the time\n; as a word like 14:05:09, and PARSE plus a little trick split it up.\n; WAIT 60 pauses for a second (WAIT counts sixtieths of a second).\n; Press Stop when you have seen enough.\n\nto hand :angle :length :width :color\n  penup home setheading :angle pendown\n  setpensize :width setpencolor :color\n  forward :length\nend\n\nto face\n  penup home pendown\n  setpensize 3 setpencolor \"black\n  penup setxy 0 -200 setheading 90 pendown\n  repeat 360 [forward 200 * 3.14159 / 180 left 1]\n  for [h 1 12] [\n    penup home setheading :h * 30 forward 175 pendown\n    setheading 0 forward 1\n  ]\nend\n\nto tick\n  local [t h m s]\n  make \"t parse map [ifelse ? = \": [\"| |] [?]] item 4 time\n  make \"h item 1 :t  make \"m item 2 :t  make \"s item 3 :t\n  clean\n  face\n  hand (remainder :h 12) * 30 + :m / 2 100 8 [40 40 60]\n  hand :m * 6 + :s / 10 150 5 [40 40 60]\n  hand :s * 6 165 2 \"red\n  hideturtle\nend\n\nclearscreen\nforever [tick wait 60]\n","diary.lgo":"; DIARY.LGO - keep notes in a file that is still there tomorrow\n;\n; OPENAPPEND opens a file and adds to the end of it, SETWRITE sends\n; PRINT there instead of the screen, and SETWRITE [] sends it back.\n; OPENREAD, SETREAD and READLIST read it back one line at a time.\n; The file lives in /projects/diary.txt on your browser's disk.\n\nmake \"file \"/projects/diary.txt\n\nto note :words\n  openappend :file\n  setwrite :file\n  print (sentence first time item 2 time item 3 time \"- :words)\n  setwrite []\n  close :file\nend\n\nto readback\n  if not filep :file [print [The diary is empty.] stop]\n  openread :file\n  setread :file\n  while [not eofp] [print readlist]\n  setread []\n  close :file\nend\n\nprint [What happened today? Type a line and press Enter:]\nnote readlist\nprint [Your diary so far:]\nreadback\n","dragon.lgo":"; DRAGON.LGO - the dragon curve, folded paper made of lines\n;\n; Fold a strip of paper in half again and again, then open every fold\n; to a right angle: the shape you get is the dragon curve. The two\n; procedures call each other, turning left and right in turn.\n\nto dragon :size :level\n  if :level = 0 [forward :size stop]\n  dragon :size :level - 1\n  left 90\n  nogard :size :level - 1\nend\n\nto nogard :size :level\n  if :level = 0 [forward :size stop]\n  dragon :size :level - 1\n  right 90\n  nogard :size :level - 1\nend\n\nclearscreen hideturtle\npenup setxy -120 80 pendown\nsetpencolor [200 60 40]\ndragon 4 12\n","factorial.lgo":"; FACTORIAL.LGO - recursion you can watch, step by step\n;\n; 5! (five factorial) is 5 x 4 x 3 x 2 x 1. A recursive definition says\n; the same thing: the factorial of N is N times the factorial of N - 1,\n; and the factorial of 0 is 1.\n;\n; Try the debugger:\n;   1. Click in the margin next to the line \"if :n = 0 [output 1]\".\n;   2. Press F5. The program stops there.\n;   3. Open Call Stack: one FACTORIAL is waiting inside another.\n;   4. Click an older frame to see its own :n in Variables.\n;   5. Press F5 to continue, or F11 to take one step at a time.\n\nto factorial :n\n  if :n = 0 [output 1]\n  output :n * factorial :n - 1\nend\n\nfor [i 0 10] [print (sentence :i \"! \"= factorial :i)]\n","flower.lgo":"; FLOWER.LGO - petals made of arcs, in every colour of the palette\n;\n; A petal is two arcs back to back. Turning a little after each petal\n; makes a flower. REPCOUNT tells us which time round the loop we are,\n; so we can use it to pick a different colour for each petal.\n\nto petal :size\n  repeat 2 [arc2 60 :size right 120]\nend\n\n; ARC2 walks the turtle along an arc (ARC itself leaves the turtle still)\nto arc2 :angle :radius\n  repeat :angle / 3 [forward :radius * 3.14159 / 60 right 3]\nend\n\nto flower :petals\n  repeat :petals [\n    setpencolor remainder repcount 15\n    petal 120\n    right 360 / :petals\n  ]\nend\n\nclearscreen\nsetpensize 2\nflower 12\nhideturtle\n","guess.lgo":"; GUESS.LGO - guess the number the turtle is thinking of\n;\n; READWORD waits for you to type in the command center and press\n; Enter. NUMBERP checks that what you typed really is a number.\n\nto play\n  make \"secret 1 + random 100\n  make \"tries 0\n  print [I am thinking of a number from 1 to 100.]\n  guess\nend\n\nto guess\n  type [Your guess? ]\n  make \"g readword\n  if not numberp :g [print [That is not a number. Try again.] guess stop]\n  make \"tries :tries + 1\n  if :g < :secret [print [Higher!] guess stop]\n  if :g > :secret [print [Lower!] guess stop]\n  print (sentence [Yes! It was] :secret [and you needed] :tries [tries.])\nend\n\nplay\n","hanoi.lgo":"; HANOI.LGO - the Towers of Hanoi, solved by recursion\n;\n; Move a tower of discs from one peg to another, one disc at a time,\n; never putting a bigger disc on a smaller one. To move N discs: move\n; N-1 out of the way, move the biggest, then move the N-1 back on top.\n\nmake \"moves 0\n\nto hanoi :n :from :to :via\n  if :n = 0 [stop]\n  hanoi :n - 1 :from :via :to\n  make \"moves :moves + 1\n  print (sentence [Move disc] :n [from] :from [to] :to)\n  hanoi :n - 1 :via :to :from\nend\n\nhanoi 4 \"left \"right \"middle\nprint (sentence [That took] :moves [moves.])\n","mouse.lgo":"; MOUSE.LGO - draw with the mouse\n;\n; MOUSEON takes five instruction lists: what to do when the left button\n; goes down, when it comes up, the same for the right button, and when\n; the mouse moves. The program keeps running in the background while\n; the lists react to the mouse. Press Stop to finish.\n\nmake \"drawing \"false\nto down\n  make \"drawing \"true\n  penup setpos mousepos pendown\nend\nto move\n  if :drawing [setpos mousepos]\nend\n\nclearscreen\nsetpensize 3\nsetpencolor [200 70 140]\nmouseon [down] [make \"drawing \"false] [clean] [] [move]\nprint [Hold the left button down and move the mouse to draw. Right-click to clear.]\nforever [wait 6]\n","multi.lgo":"; MULTI.LGO - one program in two files\n;\n; LOAD reads another file: it defines the procedures in it and runs any\n; instructions it has. Here the shapes live in shapes.lgo, next to this\n; file, and this file uses them.\n\nload \"/examples/shapes.lgo\nclearscreen hideturtle\nfor [i 1 6] [\n  setpencolor :i\n  house 40 + 15 * :i\n  penup right 60 forward 10 pendown\n]\n","music.lgo":"; MUSIC.LGO - a tune played on the speaker\n;\n; SOUND takes a list of pairs: a frequency in hertz and how many\n; milliseconds to play it. A list of note names is turned into\n; frequencies with a property list.\n\npprop \"notes \"c 262  pprop \"notes \"d 294  pprop \"notes \"e 330\npprop \"notes \"f 349  pprop \"notes \"g 392  pprop \"notes \"a 440\npprop \"notes \"b 494  pprop \"notes \"c2 523\n\nto play :tune\n  foreach :tune [\n    sound (list gprop \"notes first ? 220 * last ?)\n  ]\nend\n\n; each note is [name beats]\nplay [[c 1] [c 1] [g 1] [g 1] [a 1] [a 1] [g 2] [f 1] [f 1] [e 1] [e 1] [d 1] [d 1] [c 2]]\n","polygons.lgo":"; POLYGONS.LGO - every regular shape from a triangle to a circle\n;\n; To draw a shape with N sides, turn 360/N after each side. When N is\n; big the shape looks like a circle. FOR counts N for us.\n\nto polygon :sides :length\n  repeat :sides [forward :length right 360 / :sides]\nend\n\nclearscreen hideturtle\nfor [n 3 12] [\n  setpencolor :n\n  polygon :n 260 / :n\n  penup forward 4 pendown\n]\npenup home setxy -120 -220 pendown\nsetpencolor \"black\nlabel [Triangle to dodecagon: turn 360/N each time]\n","rainbow.lgo":"; RAINBOW.LGO - colours mixed from red, green and blue\n;\n; SETPENCOLOR can take a list of three numbers from 0 to 255: how much\n; red, green and blue to mix. Here the mix changes smoothly as the\n; turtle goes round, making a colour wheel.\n\nto wheel\n  for [angle 0 359] [\n    setpencolor (list 127 + 127 * cos :angle\n                      127 + 127 * cos :angle - 120\n                      127 + 127 * cos :angle + 120)\n    penup home setheading :angle forward 60 pendown\n    forward 200\n  ]\nend\n\nclearscreen hideturtle\nsetpensize 4\nwheel\n","shapes.lgo":"; SHAPES.LGO - shapes used by multi.lgo\n; This file only defines procedures, so running it by itself draws\n; nothing. Run multi.lgo instead.\n\nto square :size\n  repeat 4 [forward :size right 90]\nend\n\nto triangle :size\n  repeat 3 [forward :size right 120]\nend\n\nto house :size\n  square :size\n  forward :size right 30\n  triangle :size\n  left 30 back :size\nend\n","sierpinski.lgo":"; SIERPINSKI.LGO - triangles inside triangles inside triangles\n;\n; A Sierpinski triangle is three half-size Sierpinski triangles, one in\n; each corner. FILLED paints the smallest ones in solid colour.\n\nto sierpinski :size :level\n  if :level = 0 [\n    filled pick [[255 120 80] [255 180 60] [240 90 120]] [repeat 3 [forward :size right 120]]\n    stop\n  ]\n  repeat 3 [\n    sierpinski :size / 2 :level - 1\n    forward :size\n    right 120\n  ]\nend\n\nclearscreen hideturtle\npenup setxy -240 -200 setheading 30 pendown\nsierpinski 480 5\n","snake.lgo":"; SNAKE.LGO - steer with the arrow keys and eat the dots\n;\n; Click the turtle world first so it gets your key presses.\n; KEYP says whether a key is waiting; READCHAR reads it. The arrow keys\n; come back as the words LEFT, RIGHT, UP and DOWN.\n\nto setup\n  clearscreen hideturtle\n  setpensize 6\n  make \"score 0\n  make \"dir 0\n  make \"len 12\n  make \"body []\n  make \"x 0 make \"y 0\n  newfood\nend\n\nto newfood\n  make \"food list (random 30) * 20 - 300 (random 24) * 20 - 240\n  penup setpos :food setpencolor \"red pendown forward 0.1\nend\n\nto steer\n  if not keyp [stop]\n  make \"k readchar\n  if :k = \"UP [make \"dir 0]\n  if :k = \"RIGHT [make \"dir 90]\n  if :k = \"DOWN [make \"dir 180]\n  if :k = \"LEFT [make \"dir 270]\nend\n\nto move\n  make \"x :x + 10 * sin :dir\n  make \"y :y + 10 * cos :dir\n  if or (abs :x) > 390 (abs :y) > 290 [print (sentence [Crash! Score:] :score) throw \"toplevel]\n  penup setxy :x :y setpencolor [40 150 70] pendown forward 0.1\n  make \"body fput (list :x :y) :body\n  if (count :body) > :len [\n    penup setpos last :body setpencolor background pendown forward 0.1\n    make \"body butlast :body\n  ]\n  if (distance :food) < 12 [make \"score :score + 1 make \"len :len + 4 newfood]\nend\n\nsetup\nforever [steer move wait 3]\n","snowflake.lgo":"; SNOWFLAKE.LGO - the Koch snowflake, a famous fractal\n;\n; Every straight side is replaced by four shorter sides with a bump in\n; the middle, and every one of those by four more, and so on. The\n; LEVEL input says how many times to do the replacing.\n\nto side :size :level\n  if :level = 0 [forward :size stop]\n  side :size / 3 :level - 1\n  left 60\n  side :size / 3 :level - 1\n  right 120\n  side :size / 3 :level - 1\n  left 60\n  side :size / 3 :level - 1\nend\n\nto snowflake :size :level\n  repeat 3 [side :size :level right 120]\nend\n\nclearscreen\npenup setxy -180 100 setheading 90 pendown\nsetpencolor [30 120 210]\nsnowflake 360 4\nhideturtle\n","sorting.lgo":"; SORTING.LGO - putting a list in order, two different ways\n;\n; Lists are Logo's favourite thing. INSERT puts one number into an\n; already-sorted list; ISORT does that for every number. QSORT picks\n; the first number and sorts the smaller and bigger ones separately.\n; A ~ at the end of a line joins it to the next one.\n\nto insert :x :sorted\n  if emptyp :sorted [output (list :x)]\n  if :x <= first :sorted [output fput :x :sorted]\n  output fput first :sorted insert :x butfirst :sorted\nend\n\nto isort :list\n  if emptyp :list [output []]\n  output insert first :list isort butfirst :list\nend\n\nto qsort :list\n  if emptyp :list [output []]\n  localmake \"pivot first :list\n  output (sentence qsort filter [? < :pivot] butfirst :list ~\n                   :pivot ~\n                   qsort filter [? >= :pivot] butfirst :list)\nend\n\nmake \"numbers [42 7 19 88 3 56 21 64 11 35]\nprint sentence [Unsorted:] :numbers\nprint sentence [Insertion sort:] isort :numbers\nprint sentence [Quicksort:] qsort :numbers\n","spiral.lgo":"; SPIRAL.LGO - a squared spiral that grows a little on every turn\n;\n; Each time round the loop the turtle walks a bit further than the\n; last time and turns a bit less than a right angle. That small\n; mismatch is what makes the square twist into a spiral.\n; Try: change 91 to 89, 120 or 144. Change the 2 to 1 or 4.\n\nto spiral :size :angle :grow\n  if :size > 400 [stop]\n  forward :size\n  right :angle\n  spiral :size + :grow :angle :grow\nend\n\nclearscreen hideturtle\nsetpencolor [40 110 200]\nspiral 2 91 2\n","stars.lgo":"; STARS.LGO - a night sky with stars of every shape\n;\n; A star with an odd number of points can be drawn without lifting the\n; pen: turn by 180 - 180/points after each line. RANDOM picks where\n; each star goes and how big it is.\n\nto star :size :points\n  repeat :points [forward :size right 180 - 180 / :points]\nend\n\nto sky :count\n  repeat :count [\n    penup\n    setxy (random 760) - 380 (random 560) - 280\n    setheading random 360\n    pendown\n    setpencolor pick [yellow white orange [255 240 160]]\n    star 10 + random 30 pick [5 7 9]\n  ]\nend\n\nclearscreen\nsetbackground [12 18 48]\nhideturtle\nsky 40\n","tree.lgo":"; TREE.LGO - a recursive tree: every branch carries two smaller trees\n;\n; This is the classic example of recursion in Logo. TREE draws a trunk,\n; then calls TREE twice for the two branches, each a bit shorter.\n; When the branches get small enough it stops.\n;\n; Debugger tip: put a breakpoint on the \"forward :size\" line (click in\n; the margin) and press F5. Then open the Call Stack tab and press F11\n; a few times: you can see one TREE waiting inside another.\n\nto tree :size\n  if :size < 6 [stop]\n  setpensize :size / 8\n  setpencolor ifelse :size < 15 [[60 160 70]] [[110 70 40]]\n  forward :size\n  left 25\n  tree :size * 0.72\n  right 50\n  tree :size * 0.72\n  left 25\n  back :size\nend\n\nclearscreen\npenup setxy 0 -250 pendown\ntree 110\nhideturtle\n"};
})(LG);
